#!/bin/bash
# Publishes docs/ of this repository to vdesabou/kafka-docker-playground-docs, which serves
# https://kafka-docker-playground.io with GitHub Pages (main branch, /docs folder).
#
# docs/ holds the hand-written pages (tracked here) and, in CI, the pages generated by 'playground update-docs'
# (CLI reference), 'playground update-readme' (content.md, badges.md, introduction.md) and update-changelogs.yml
# (changelog.md). The docs repository keeps the media (videos/, images/, reports/) and the scripts recording them.
#
# usage: API_TOKEN_GITHUB=<token> scripts/publish-docs.sh [--dry-run] ["<commit message>"]
#   --dry-run  prepare the commit in a temporary clone and show it, without pushing
#   without API_TOKEN_GITHUB, the clone and the push use your own git credentials

set -e

function log() {
  YELLOW='\033[0;33m'
  NC='\033[0m' # No Color
  echo -e "$YELLOW$@$NC"
}

function logerror() {
  RED='\033[0;31m'
  NC='\033[0m' # No Color
  echo -e "$RED$@$NC"
}

dry_run=0
if [ "$1" == "--dry-run" ]
then
  dry_run=1
  shift
fi
commit_message="${1:-updating with latest versions}"

root_folder="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
docs_repo="vdesabou/kafka-docker-playground-docs"
if [ -n "$API_TOKEN_GITHUB" ]
then
  docs_repo_url="https://x-access-token:${API_TOKEN_GITHUB}@github.com/${docs_repo}.git"
else
  docs_repo_url="https://github.com/${docs_repo}.git"
fi
# at the root of the docs repository: files of docs/ tracked here at the last publication, so that a page
# removed or renamed here is also removed there (generated pages are not tracked, they are never in this list)
manifest=".published-from-kafka-docker-playground"
tracked_files=$(git -C "$root_folder" -c core.quotePath=false ls-files docs | sed 's#^docs/##' | sort)

work_dir=$(mktemp -d)
trap 'rm -rf "$work_dir"' EXIT

for attempt in 1 2 3 4 5
do
  rm -rf "$work_dir/docs-repo"
  git clone --quiet --depth 1 "$docs_repo_url" "$work_dir/docs-repo"
  cd "$work_dir/docs-repo"

  if [ -f "$manifest" ]
  then
    comm -23 "$manifest" <(echo "$tracked_files") | while IFS= read -r file
    do
      log "🗑️ removing docs/$file, no longer in kafka-docker-playground"
      rm -f "docs/$file"
    done
  fi
  # CLI reference pages are all re-generated by playground update-docs: remove the existing ones first
  if ls "$root_folder"/docs/playground\ *.md > /dev/null 2>&1
  then
    rm -f docs/playground\ *.md
  fi
  cp -R "$root_folder/docs/." docs/
  echo "$tracked_files" > "$manifest"

  git config user.email 'vincent.desaboulin@gmail.com'
  git config user.name 'vdesabou'
  git add -A docs "$manifest"
  if git diff --cached --quiet
  then
    log "✅ nothing to publish, ${docs_repo} is up to date"
    exit 0
  fi
  git commit --quiet -m "$commit_message"

  if [ $dry_run -eq 1 ]
  then
    log "🧪 --dry-run: would push this commit to ${docs_repo}"
    git show --stat --format='%s' HEAD | cat
    exit 0
  fi

  if git push --quiet origin main
  then
    log "🚀 published to ${docs_repo}: $(git rev-parse --short HEAD)"
    exit 0
  fi
  # another workflow pushed in the meantime: start again from a fresh clone
  log "🔁 push rejected (attempt $attempt/5), retrying from a fresh clone"
  cd "$root_folder"
  sleep $((attempt * 10))
done

logerror "❌ could not publish to ${docs_repo} after 5 attempts"
exit 1
